import{c as t,Q as o,j as a,m as i}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Compiling Agentic Workflows into LLM Weights: Near-Frontier Quality at Two Orders of Magnitude Less Cost","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.22502","title":"Compiling Agentic Workflows into LLM Weights: Near-Frontier Quality at Two Orders of Magnitude Less Cost","archived_date":"2026-07-31T00:00:00.000Z","arxiv_id":2605.22502,"authors":["Simon Dennis","Rivaan Patil","Kevin Shabahang","Hao Guo"],"collected_at":"2026-07-31T00:00:00.000Z","collected_by":"routine-d","domain":"loop-workflow-engineering","pdf_path":"pdfs/2605.22502.pdf","published_date":"2026-05-21T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-05-21-compiling-agentic-workflows-into-llm-weights-2605-22502.md","filePath":"research/papers/2026-05-21-compiling-agentic-workflows-into-llm-weights-2605-22502.md","lastUpdated":1785909234000}'),r={name:"research/papers/2026-05-21-compiling-agentic-workflows-into-llm-weights-2605-22502.md"};function s(n,e,l,c,d,g){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="compiling-agentic-workflows-into-llm-weights-near-frontier-quality-at-two-orders-of-magnitude-less-cost" tabindex="-1">Compiling Agentic Workflows into LLM Weights: Near-Frontier Quality at Two Orders of Magnitude Less Cost <a class="header-anchor" href="#compiling-agentic-workflows-into-llm-weights-near-frontier-quality-at-two-orders-of-magnitude-less-cost" aria-label="Permalink to &quot;Compiling Agentic Workflows into LLM Weights: Near-Frontier Quality at Two Orders of Magnitude Less Cost&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>質疑業界偏好編排框架（orchestration framework）而非把流程直接編譯進模型權重（fine-tuned weights）的現況，即便後者在程序性任務上實證表現更佳。作者以三個案例研究（14 節點的旅遊訂票、含產品知識的 14 節點 Zoom 支援、55 節點/6 決策樞紐的保險理賠）逐一拆解並實證反駁三項普遍認知障礙，主張把流程編譯進權重可避免 context 消耗、降低對前沿模型的依賴，並保護專有流程不外洩給第三方。</p><h2 id="與-harness-的關聯" tabindex="-1">與 Harness 的關聯 <a class="header-anchor" href="#與-harness-的關聯" aria-label="Permalink to &quot;與 Harness 的關聯&quot;">​</a></h2><p>這是對 <code>core.md</code>「判斷 vs 決定」公理的一個反例式挑戰——把確定性流程編譯進模型權重，某種程度上是把「決定」重新交還給模型本身而非外部程序層；對本 repo 而言是值得警惕的對照組，說明「權重內化流程」與「harness 外部化流程」在 context 成本與供應鏈保護上的取捨各有主張，非單向定論。</p>',5)])])}const m=t(r,[["render",s]]);export{p as __pageData,m as default};
